export const envelope = [27, 42, 27];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 8;

  // 3D Voxel buffer for deterministic composition
  const vox = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function setV(x, y, z, block) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      vox[ix][iy][iz] = block;
    }
  }

  function getV(x, y, z) {
    const ix = Math.round(x);
    const iy = Math.round(y);
    const iz = Math.round(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      return vox[ix][iy][iz];
    }
    return null;
  }

  // Palette aliases
  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_spruce_log";
  const woodSlab = api.theme.wood.slab || "minecraft:spruce_slab";
  const woodStairs = api.theme.wood.stairs || "minecraft:spruce_stairs";
  const woodFence = api.theme.wood.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:spruce_trapdoor";
  const stonePrimary = api.theme.stone.primary || "minecraft:mossy_stone_bricks";
  const stoneSlab = api.theme.stone.slab || "minecraft:mossy_stone_brick_slab";
  const stoneWall = api.theme.stone.wall || "minecraft:mossy_stone_brick_wall";

  // Specialized fungal bioluminescence
  const mushroomStem = "minecraft:mushroom_stem";
  const redMushroom = "minecraft:red_mushroom_block";
  const brownMushroom = "minecraft:brown_mushroom_block";
  const shroomlight = "minecraft:shroomlight";
  const froglight = "minecraft:ochre_froglight";
  const sporeBlossom = "minecraft:spore_blossom";
  const mossBlock = "minecraft:moss_block";
  const chain = "minecraft:chain";
  const netherWart = "minecraft:nether_wart_block";

  // Centerline of the fungal stalk (slight organic curvature)
  function getCenter(y) {
    const t = y - SEAT_Y;
    const cx = 13 + 0.65 * Math.sin(t * 0.14);
    const cz = 13 + 0.45 * Math.sin(t * 0.11);
    return [cx, cz];
  }

  // Stalk outer radius function
  function getStalkRadius(y, angle) {
    let r;
    if (y < SEAT_Y) {
      r = 4.6 + (SEAT_Y - y) * 0.18;
    } else if (y <= 14) {
      const t = (y - SEAT_Y) / 6;
      r = 4.4 * (1 - t) + 3.1 * t;
    } else if (y <= 22) {
      const t = (y - 14) / 8;
      r = 3.1 * (1 - t) + 4.2 * t;
    } else {
      const t = (y - 22) / 6;
      r = 4.2 * (1 - t) + 6.8 * t;
    }

    // Root buttress flaring near base
    if (y <= 12) {
      const flare = Math.max(0, Math.cos(5 * angle + 0.35));
      const factor = (12 - y) / 8;
      r += 1.85 * flare * factor;
    }
    return r;
  }

  // Cap outer dome radius function
  function getCapOuterR(y) {
    if (y < 24) return 0;
    if (y === 24) return 7.2;
    if (y === 25) return 9.2;
    if (y === 26) return 10.7;
    if (y === 27) return 11.6;
    if (y === 28) return 11.8;
    const t = (y - 28) / 13; // 28 to 41
    if (t > 1) return 0;
    return 11.8 * Math.sqrt(Math.max(0, 1 - Math.pow(t, 1.35)));
  }

  // Cap interior void (Sacred Fungal Hall)
  function getHallR(y) {
    if (y < 28 || y > 35) return 0;
    const capR = getCapOuterR(y);
    return Math.max(0, capR - 2.0);
  }

  // 1. Build the Main Fungal Stalk
  for (let y = SEAT_Y; y <= 27; y++) {
    const [cx, cz] = getCenter(y);
    const rMax = getStalkRadius(y, 0) + 2.5;
    const minX = Math.max(0, Math.floor(cx - rMax));
    const maxX = Math.min(W - 1, Math.ceil(cx + rMax));
    const minZ = Math.max(0, Math.floor(cz - rMax));
    const maxZ = Math.min(D - 1, Math.ceil(cz + rMax));

    for (let x = minX; x <= maxX; x++) {
      for (let z = minZ; z <= maxZ; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const d = Math.sqrt(dx * dx + dz * dz);
        const angle = Math.atan2(dz, dx);
        const rStalk = getStalkRadius(y, angle);

        if (d <= rStalk) {
          const isOuter = d > rStalk - 0.9;
          if (isOuter) {
            setV(x, y, z, mushroomStem);
          } else {
            // Core tissue with occasional bioluminescent veins
            if ((x * 3 + y * 7 + z * 5) % 19 === 0) {
              setV(x, y, z, shroomlight);
            } else if ((x + z + y) % 2 === 0) {
              setV(x, y, z, woodStripped);
            } else {
              setV(x, y, z, mushroomStem);
            }
          }
        }
      }
    }
  }

  // 2. Terrain Conformance (Rule 6: skirt down to real ground on all columns)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const [cx, cz] = getCenter(SEAT_Y);
      const dx = x - cx;
      const dz = z - cz;
      const d = Math.sqrt(dx * dx + dz * dz);
      const angle = Math.atan2(dz, dx);
      const baseR = getStalkRadius(SEAT_Y, angle);

      if (d <= baseR + 1.2) {
        const groundHeight = api.heightAt(x, z);
        const nodeGroundY = Math.max(0, Math.min(H - 1, SEAT_Y + Math.round(groundHeight)));

        if (nodeGroundY < SEAT_Y) {
          // Ground falls away: build downward skirt to meet terrain
          for (let y = nodeGroundY; y < SEAT_Y; y++) {
            const isRim = d > baseR - 0.5;
            setV(x, y, z, isRim ? woodLog : mushroomStem);
          }
        } else if (nodeGroundY > SEAT_Y) {
          // Ground rises: thicken base upward to meet rising hillside
          for (let y = SEAT_Y; y <= Math.min(nodeGroundY, 16); y++) {
            setV(x, y, z, mushroomStem);
          }
        }

        // Add root toe anchors on surface
        if (d > baseR - 0.6 && d <= baseR + 1.5 && nodeGroundY >= 0 && nodeGroundY < H) {
          setV(x, nodeGroundY, z, (x + z) % 2 === 0 ? mossBlock : woodLog);
        }
      }
    }
  }

  // 3. Spiraling Shelf-Bracket Fungi Steps (wrapping the exterior stalk)
  // Terminus angle aligns with the sacred hall entrance
  const entranceAngle = 2.40;
  const numSteps = 20;
  const angleStepRate = 0.38;
  const startAngle = entranceAngle - numSteps * angleStepRate;

  for (let s = 0; s <= numSteps; s++) {
    const yStep = SEAT_Y + s;
    const angle = startAngle + s * angleStepRate;
    const [cx, cz] = getCenter(yStep);
    const rTrunk = getStalkRadius(yStep, angle);

    const rMin = rTrunk - 0.2;
    const rMax = rTrunk + 1.75;
    const angleSpan = 0.32;

    const shelfX = cx + (rTrunk + 0.8) * Math.cos(angle);
    const shelfZ = cz + (rTrunk + 0.8) * Math.sin(angle);

    for (let da = -angleSpan; da <= angleSpan; da += 0.08) {
      const curAngle = angle + da;
      for (let r = rMin; r <= rMax; r += 0.5) {
        const px = Math.round(cx + r * Math.cos(curAngle));
        const pz = Math.round(cz + r * Math.sin(curAngle));

        // Step tread
        setV(px, yStep, pz, brownMushroom);

        // Bracket fungal support & under-step bioluminescence
        if (yStep - 1 >= 0) {
          if (r < rMin + 0.8) {
            setV(px, yStep - 1, pz, mushroomStem);
          } else if ((px + pz) % 3 === 0) {
            setV(px, yStep - 1, pz, shroomlight);
          } else {
            setV(px, yStep - 1, pz, woodSlab);
          }
        }
      }
    }

    // Outer shelf safety rail posts at intervals
    if (s % 3 === 0 && s < numSteps) {
      const rx = Math.round(cx + (rMax + 0.1) * Math.cos(angle));
      const rz = Math.round(cz + (rMax + 0.1) * Math.sin(angle));
      setV(rx, yStep + 1, rz, woodFence);
    }
  }

  // 4. Underside Gills & Bioluminescent Channels (y = 24 to 27)
  for (let y = 24; y <= 27; y++) {
    const [cx, cz] = getCenter(y);
    const capR = getCapOuterR(y);
    const minX = Math.max(0, Math.floor(cx - capR));
    const maxX = Math.min(W - 1, Math.ceil(cx + capR));
    const minZ = Math.max(0, Math.floor(cz - capR));
    const maxZ = Math.min(D - 1, Math.ceil(cz + capR));

    for (let x = minX; x <= maxX; x++) {
      for (let z = minZ; z <= maxZ; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const d = Math.sqrt(dx * dx + dz * dz);
        const angle = Math.atan2(dz, dx);
        const rStalk = getStalkRadius(y, angle);

        if (d >= rStalk - 0.4 && d <= capR) {
          const gillWave = Math.cos(22 * angle);
          if (d > capR - 1.0) {
            // Outer cap rim margin
            setV(x, y, z, mushroomStem);
          } else if (gillWave > 0.35) {
            // Structural gill fin
            setV(x, y, z, mushroomStem);
          } else if (gillWave < -0.3) {
            // Glowing bioluminescent channel between gills
            setV(x, y, z, (x + z) % 3 === 0 ? froglight : shroomlight);
          } else {
            setV(x, y, z, mushroomStem);
          }
        }
      }
    }
  }

  // Hanging spore tendrils beneath the gills
  const numTendrils = 14;
  for (let i = 0; i < numTendrils; i++) {
    const tAngle = (i / numTendrils) * Math.PI * 2 + 0.15;
    const [cx, cz] = getCenter(26);
    const tRadius = getCapOuterR(26) - 1.1;
    const tx = Math.round(cx + tRadius * Math.cos(tAngle));
    const tz = Math.round(cz + tRadius * Math.sin(tAngle));

    const dropLen = 2 + (i % 3);
    for (let dy = 1; dy <= dropLen; dy++) {
      const curY = 25 - dy;
      if (curY >= 0) {
        if (dy === dropLen) {
          setV(tx, curY, tz, i % 2 === 0 ? sporeBlossom : shroomlight);
        } else {
          setV(tx, curY, tz, chain);
        }
      }
    }
  }

  // 5. Cap Outer Shell & Cream Wart Spots (y = 28 to 41)
  // Deterministic spot center anchors on the dome
  const spotAnchors = [
    [0.65, 0.2], [0.80, 1.2], [0.70, 2.3], [0.85, 3.5], [0.75, 4.6], [0.80, 5.7],
    [1.15, 0.6], [1.10, 1.9], [1.20, 3.0], [1.12, 4.1], [1.18, 5.2],
    [0.32, 0.9], [0.35, 3.6], [0.38, 5.3]
  ];

  const spotPoints = spotAnchors.map(([zenith, azimuth]) => {
    const sy = 40.5 - 11.5 * (1 - Math.cos(zenith));
    const [scx, scz] = getCenter(sy);
    const sr = getCapOuterR(sy) - 0.3;
    const sx = scx + sr * Math.cos(azimuth) * Math.sin(zenith);
    const sz = scz + sr * Math.sin(azimuth) * Math.sin(zenith);
    return [sx, sy, sz];
  });

  for (let y = 28; y <= 41; y++) {
    const [cx, cz] = getCenter(y);
    const capR = getCapOuterR(y);
    const hallR = getHallR(y);

    const minX = Math.max(0, Math.floor(cx - capR));
    const maxX = Math.min(W - 1, Math.ceil(cx + capR));
    const minZ = Math.max(0, Math.floor(cz - capR));
    const maxZ = Math.min(D - 1, Math.ceil(cz + capR));

    for (let x = minX; x <= maxX; x++) {
      for (let z = minZ; z <= maxZ; z++) {
        const dx = x - cx;
        const dz = z - cz;
        const d = Math.sqrt(dx * dx + dz * dz);

        if (d <= capR && d >= hallR) {
          // Check if close to any cream spot center
          let isSpot = false;
          for (let i = 0; i < spotPoints.length; i++) {
            const [sx, sy, sz] = spotPoints[i];
            const distSq = (x - sx) ** 2 + (y - sy) ** 2 + (z - sz) ** 2;
            if (distSq <= 2.4) {
              isSpot = true;
              break;
            }
          }

          if (isSpot) {
            setV(x, y, z, mushroomStem);
          } else {
            // Rich fungal red canopy with organic nether wart texture
            const textureHash = (x * 7 + y * 13 + z * 19) % 7;
            setV(x, y, z, textureHash === 0 ? netherWart : redMushroom);
          }
        }
      }
    }
  }

  // 6. Sacred Fungal Hall: Solid Floor at y = 27
  const [floorCx, floorCz] = getCenter(27);
  const floorR = getCapOuterR(27) - 0.7;
  for (let x = Math.floor(floorCx - floorR); x <= Math.ceil(floorCx + floorR); x++) {
    for (let z = Math.floor(floorCz - floorR); z <= Math.ceil(floorCz + floorR); z++) {
      const dx = x - floorCx;
      const dz = z - floorCz;
      const d = Math.sqrt(dx * dx + dz * dz);
      if (d <= floorR) {
        if (d <= 2.2) {
          setV(x, 27, z, stonePrimary);
        } else if (d <= 3.8 && d >= 3.0) {
          setV(x, 27, z, shroomlight);
        } else {
          setV(x, 27, z, woodPlanks);
        }
      }
    }
  }

  // 7. Hall Interior Fit-Out & Architectural Carvings
  // A. Entrance Archway at spiral stair head (angle ~ 2.40)
  for (let y = 28; y <= 30; y++) {
    const [cx, cz] = getCenter(y);
    for (let da = -0.25; da <= 0.25; da += 0.08) {
      const curAngle = entranceAngle + da;
      for (let r = getHallR(y) - 0.5; r <= getCapOuterR(y) + 0.8; r += 0.5) {
        const px = Math.round(cx + r * Math.cos(curAngle));
        const pz = Math.round(cz + r * Math.sin(curAngle));
        setV(px, y, pz, null); // Hollow out doorway
      }
    }
  }
  // Doorway threshold & frame
  const doorOuterX = Math.round(floorCx + (getCapOuterR(27) + 0.2) * Math.cos(entranceAngle));
  const doorOuterZ = Math.round(floorCz + (getCapOuterR(27) + 0.2) * Math.sin(entranceAngle));
  setV(doorOuterX, 27, doorOuterZ, woodPlanks);

  // B. Balcony Scenic Windows cut into cap wall
  const windowAngles = [-Math.PI / 2, Math.PI, Math.PI / 4];
  windowAngles.forEach((wAngle) => {
    for (let wy = 29; wy <= 30; wy++) {
      const [cx, cz] = getCenter(wy);
      for (let da = -0.15; da <= 0.15; da += 0.08) {
        const curA = wAngle + da;
        for (let r = getHallR(wy) - 0.2; r <= getCapOuterR(wy); r += 0.5) {
          const wx = Math.round(cx + r * Math.cos(curA));
          const wz = Math.round(cz + r * Math.sin(curA));
          if (r >= getCapOuterR(wy) - 0.8) {
            setV(wx, wy, wz, woodFence);
          } else {
            setV(wx, wy, wz, null);
          }
        }
      }
    }
  });

  // C. Central Sacred Shrine & Altar (y = 28 to 29)
  setV(floorCx, 28, floorCz, shroomlight);
  setV(floorCx, 29, floorCz, froglight);
  setV(floorCx + 1, 28, floorCz, stoneWall);
  setV(floorCx - 1, 28, floorCz, stoneWall);
  setV(floorCx, 28, floorCz + 1, stoneWall);
  setV(floorCx, 28, floorCz - 1, stoneWall);

  // D. Ceiling Hanging Chandelier & Spore Bloom (y = 33 to 36)
  const [ceilCx, ceilCz] = getCenter(35);
  setV(ceilCx, 36, ceilCz, shroomlight);
  setV(ceilCx, 35, ceilCz, chain);
  setV(ceilCx, 34, ceilCz, shroomlight);
  setV(ceilCx, 33, ceilCz, sporeBlossom); // Fills hollow hall with glowing green spores

  // 8. Ground Level Fungal Grotto (Base archway for ground exploration)
  const [baseCx, baseCz] = getCenter(SEAT_Y);
  for (let gy = SEAT_Y; gy <= SEAT_Y + 3; gy++) {
    for (let gx = Math.round(baseCx - 1); gx <= Math.round(baseCx + 1); gx++) {
      for (let gz = Math.round(baseCz - getStalkRadius(SEAT_Y, -Math.PI / 2) - 1); gz <= Math.round(baseCz); gz++) {
        const dCenter = Math.sqrt((gx - baseCx) ** 2 + (gz - baseCz) ** 2);
        if (dCenter <= 2.2 || gz < baseCz - 1.5) {
          setV(gx, gy, gz, null); // Hollow entrance portal
        }
      }
    }
  }
  // Grotto interior shrine light
  setV(baseCx, SEAT_Y, baseCz, shroomlight);
  setV(baseCx, SEAT_Y + 1, baseCz, woodFence);

  // 9. Commit Voxel Buffer to API
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = vox[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "ancient_mother_glowcap",
    seatY: SEAT_Y,
    anchors: {
      front: [13, SEAT_Y, 0],
      door: [13, SEAT_Y, 8],
      hall_door: [doorOuterX, 28, doorOuterZ]
    },
    interiors: [
      {
        min: [9, 28, 9],
        max: [17, 33, 17],
        kind: "hall"
      }
    ]
  };
}

glow_fungal_cluster.source:
export const envelope = [11, 15, 11];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 3;
  const cx = 5;
  const cz = 5;

  // Grid initialization
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function setVoxel(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function getVoxel(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x][y][z];
    }
    return null;
  }

  // Palette variations across instances
  const themeIndex = (api.instance.index + Math.floor(api.random() * 2)) % 4;

  const palettes = [
    // 0: Warped Cyan Bioluminescence
    {
      stem: "minecraft:mushroom_stem",
      stemAccent: "minecraft:stripped_warped_stem",
      capOuter: "minecraft:warped_wart_block",
      capAccent: "minecraft:cyan_concrete_powder",
      glowCore: "minecraft:verdant_froglight",
      glowSub: "minecraft:shroomlight",
      gills: "minecraft:warped_hyphae",
      tendril: "minecraft:verdant_froglight",
      surfaceMoss: "minecraft:moss_block",
      surfaceMycelium: "minecraft:warped_nylium",
      rootBlock: "minecraft:stripped_warped_stem",
    },
    // 1: Crimson Scarlet Glow
    {
      stem: "minecraft:mushroom_stem",
      stemAccent: "minecraft:stripped_crimson_stem",
      capOuter: "minecraft:red_mushroom_block",
      capAccent: "minecraft:nether_wart_block",
      glowCore: "minecraft:pearlescent_froglight",
      glowSub: "minecraft:shroomlight",
      gills: "minecraft:crimson_hyphae",
      tendril: "minecraft:pearlescent_froglight",
      surfaceMoss: "minecraft:moss_block",
      surfaceMycelium: "minecraft:crimson_nylium",
      rootBlock: "minecraft:stripped_crimson_stem",
    },
    // 2: Amber Ochre & Honeyed Shelf
    {
      stem: "minecraft:mushroom_stem",
      stemAccent: "minecraft:stripped_oak_log",
      capOuter: "minecraft:brown_mushroom_block",
      capAccent: "minecraft:honeycomb_block",
      glowCore: "minecraft:ochre_froglight",
      glowSub: "minecraft:shroomlight",
      gills: "minecraft:brown_mushroom_block",
      tendril: "minecraft:ochre_froglight",
      surfaceMoss: "minecraft:moss_block",
      surfaceMycelium: "minecraft:podzol",
      rootBlock: "minecraft:mushroom_stem",
    },
    // 3: Twilight Mystic Amethyst
    {
      stem: "minecraft:mushroom_stem",
      stemAccent: "minecraft:stripped_warped_hyphae",
      capOuter: "minecraft:purpur_block",
      capAccent: "minecraft:warped_wart_block",
      glowCore: "minecraft:pearlescent_froglight",
      glowSub: "minecraft:verdant_froglight",
      gills: "minecraft:warped_wart_block",
      tendril: "minecraft:shroomlight",
      surfaceMoss: "minecraft:moss_block",
      surfaceMycelium: "minecraft:mycelium",
      rootBlock: "minecraft:stripped_warped_hyphae",
    },
  ];

  const palette = palettes[themeIndex];
  const plinthTheme = api.theme?.ground?.plinth || "minecraft:rooted_dirt";
  const pavementTheme = api.theme?.ground?.pavement || "minecraft:moss_block";

  // 1. Central Mycelium & Root Mound (Conforms to terrain heightAt)
  const baseRx = 3.3 + api.random() * 0.9;
  const baseRz = 3.3 + api.random() * 0.9;
  const moundPhase = api.random() * Math.PI * 2;

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const angle = Math.atan2(dz, dx);
      const radiusMod = 1.0 + 0.18 * Math.sin(3 * angle + moundPhase);
      const normDist = Math.hypot(dx / baseRx, dz / baseRz) / radiusMod;

      if (normDist <= 1.0) {
        const rawH = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(H - 1, Math.round(seatY + rawH)));
        const moundElev = Math.round((1.0 - normDist) * 1.8);
        const topY = Math.min(H - 2, Math.max(groundY, seatY + moundElev));
        const startY = Math.min(groundY, seatY);

        for (let y = startY; y <= topY; y++) {
          if (y === topY) {
            const pick = api.random();
            if (pick < 0.45) setVoxel(x, y, z, palette.surfaceMycelium);
            else if (pick < 0.75) setVoxel(x, y, z, palette.surfaceMoss);
            else setVoxel(x, y, z, pavementTheme);
          } else if (y >= topY - 1) {
            setVoxel(x, y, z, plinthTheme);
          } else {
            setVoxel(x, y, z, "minecraft:rooted_dirt");
          }
        }
      }
    }
  }

  // 2. Generate Stalks
  const numStalks = 3 + Math.floor(api.random() * 3); // 3 to 5 stalks
  const stalks = [];

  // Main Stalk
  const mainLeanAngle = api.random() * Math.PI * 2;
  const mainLeanDist = 0.8 + api.random() * 0.9;
  const mainHeight = 9 + Math.floor(api.random() * 3); // 9 to 11 tall
  stalks.push({
    bx: cx + (api.random() - 0.5) * 1.2,
    bz: cz + (api.random() - 0.5) * 1.2,
    tx: cx + Math.cos(mainLeanAngle) * mainLeanDist,
    tz: cz + Math.sin(mainLeanAngle) * mainLeanDist,
    height: mainHeight,
    baseR: 1.5,
    midR: 1.1,
    topR: 1.7,
    capR: 3.3 + api.random() * 0.7,
    capType: Math.floor(api.random() * 3),
    isMain: true,
  });

  // Secondary Stalk
  const secAngle = mainLeanAngle + Math.PI * (0.65 + api.random() * 0.5);
  const secDist = 1.8 + api.random() * 0.8;
  stalks.push({
    bx: cx + Math.cos(secAngle) * 1.6,
    bz: cz + Math.sin(secAngle) * 1.6,
    tx: cx + Math.cos(secAngle) * secDist,
    tz: cz + Math.sin(secAngle) * secDist,
    height: 6 + Math.floor(api.random() * 3),
    baseR: 1.2,
    midR: 0.9,
    topR: 1.3,
    capR: 2.2 + api.random() * 0.5,
    capType: Math.floor(api.random() * 3),
    isMain: false,
  });

  // Tertiary Stalk
  const tertAngle = mainLeanAngle - Math.PI * (0.65 + api.random() * 0.5);
  const tertDist = 1.6 + api.random() * 0.8;
  stalks.push({
    bx: cx + Math.cos(tertAngle) * 1.5,
    bz: cz + Math.sin(tertAngle) * 1.5,
    tx: cx + Math.cos(tertAngle) * tertDist,
    tz: cz + Math.sin(tertAngle) * tertDist,
    height: 4 + Math.floor(api.random() * 3),
    baseR: 1.0,
    midR: 0.8,
    topR: 1.1,
    capR: 1.7 + api.random() * 0.5,
    capType: Math.floor(api.random() * 2),
    isMain: false,
  });

  // Extra Sprouts
  for (let i = 3; i < numStalks; i++) {
    const sprAngle = api.random() * Math.PI * 2;
    const sprDist = 2.2 + api.random() * 0.8;
    stalks.push({
      bx: cx + Math.cos(sprAngle) * sprDist,
      bz: cz + Math.sin(sprAngle) * sprDist,
      tx: cx + Math.cos(sprAngle) * (sprDist + 0.5),
      tz: cz + Math.sin(sprAngle) * (sprDist + 0.5),
      height: 3 + Math.floor(api.random() * 2),
      baseR: 0.8,
      midR: 0.7,
      topR: 0.9,
      capR: 1.3 + api.random() * 0.4,
      capType: 0,
      isMain: false,
    });
  }

  let mainApex = [cx, seatY + mainHeight, cz];

  // Render Stalks and Caps
  for (const st of stalks) {
    const rawH = api.heightAt(Math.round(st.bx), Math.round(st.bz));
    const stalkBaseY = Math.max(0, Math.min(H - 2, Math.round(seatY + rawH)));
    const apexY = Math.min(H - 2, stalkBaseY + st.height);

    if (st.isMain) {
      mainApex = [Math.round(st.tx), apexY, Math.round(st.tz)];
    }

    // Quadratic Bezier Control Point
    const midX = (st.bx + st.tx) * 0.5 + (api.random() - 0.5) * 0.6;
    const midZ = (st.bz + st.tz) * 0.5 + (api.random() - 0.5) * 0.6;
    const midY = (stalkBaseY + apexY) * 0.5;

    // Build Stalk Stem
    const steps = 18;
    for (let s = 0; s <= steps; s++) {
      const t = s / steps;
      const oneMinusT = 1 - t;
      const px = oneMinusT * oneMinusT * st.bx + 2 * oneMinusT * t * midX + t * t * st.tx;
      const py = oneMinusT * oneMinusT * stalkBaseY + 2 * oneMinusT * t * midY + t * t * apexY;
      const pz = oneMinusT * oneMinusT * st.bz + 2 * oneMinusT * t * midZ + t * t * st.tz;

      let r = st.midR;
      if (t < 0.3) {
        r = st.baseR * (1.0 - t / 0.3) + st.midR * (t / 0.3);
      } else if (t > 0.7) {
        r = st.midR * ((1.0 - t) / 0.3) + st.topR * ((t - 0.7) / 0.3);
      }

      const minX = Math.max(0, Math.floor(px - r));
      const maxX = Math.min(W - 1, Math.ceil(px + r));
      const minY = Math.max(0, Math.floor(py - 0.6));
      const maxY = Math.min(H - 1, Math.ceil(py + 0.6));
      const minZ = Math.max(0, Math.floor(pz - r));
      const maxZ = Math.min(D - 1, Math.ceil(pz + r));

      for (let vx = minX; vx <= maxX; vx++) {
        for (let vy = minY; vy <= maxY; vy++) {
          for (let vz = minZ; vz <= maxZ; vz++) {
            const dist = Math.hypot(vx - px, vz - pz);
            if (dist <= r) {
              const pRand = api.random();
              let blk = palette.stem;
              if (pRand < 0.12) blk = palette.glowSub;
              else if (pRand < 0.28) blk = palette.stemAccent;
              setVoxel(vx, vy, vz, blk);
            }
          }
        }
      }

      // If at base, ensure connected downwards to terrain
      if (s === 0) {
        const floorY = Math.max(0, Math.min(H - 1, Math.round(seatY + api.heightAt(Math.round(px), Math.round(pz)))));
        for (let vy = floorY; vy <= Math.round(py); vy++) {
          setVoxel(Math.round(px), vy, Math.round(pz), palette.stem);
        }
      }
    }

    // Bracket shelf fungi on taller stalks
    if (st.height >= 6 && api.random() < 0.8) {
      const shelfY = Math.min(H - 3, stalkBaseY + 2 + Math.floor(api.random() * (st.height - 4)));
      const shelfAngle = api.random() * Math.PI * 2;
      const shX = Math.round(st.bx + Math.cos(shelfAngle) * 1.3);
      const shZ = Math.round(st.bz + Math.sin(shelfAngle) * 1.3);
      setVoxel(shX, shelfY, shZ, palette.capOuter);
      setVoxel(shX, shelfY - 1, shZ, palette.glowCore);
    }

    // 3. Build Mushroom Cap
    const capX = Math.round(st.tx);
    const capY = apexY;
    const capZ = Math.round(st.tz);
    const cR = st.capR;

    if (st.capType === 0) {
      // Bell / Dome Cap with Glowing Core
      const capH = Math.min(3, H - 1 - capY);
      const botY = Math.max(stalkBaseY + 1, capY - 1);
      const topCapY = Math.min(H - 1, capY + capH);

      for (let y = botY; y <= topCapY; y++) {
        const v = (y - botY) / Math.max(1, topCapY - botY);
        const layerR = cR * Math.sin(Math.PI * (0.2 + 0.8 * (1.0 - v)));

        const minX = Math.max(0, Math.floor(capX - layerR));
        const maxX = Math.min(W - 1, Math.ceil(capX + layerR));
        const minZ = Math.max(0, Math.floor(capZ - layerR));
        const maxZ = Math.min(D - 1, Math.ceil(capZ + layerR));

        for (let x = minX; x <= maxX; x++) {
          for (let z = minZ; z <= maxZ; z++) {
            const d = Math.hypot(x - capX, z - capZ);
            if (d <= layerR) {
              if (d >= layerR - 0.85 || y === topCapY) {
                // Outer Shell
                const dot = ((x + y + z) % 3 === 0 && api.random() < 0.35);
                setVoxel(x, y, z, dot ? palette.capAccent : palette.capOuter);
              } else if (y === botY) {
                // Underside gills
                setVoxel(x, y, z, (d <= 1.2) ? palette.glowCore : palette.gills);
              } else {
                // Glowing heart
                setVoxel(x, y, z, palette.glowCore);
              }
            }
          }
        }
      }

      // Spore Dripping Tendrils under rim
      for (let angleDeg = 0; angleDeg < 360; angleDeg += 45) {
        if (api.random() < 0.6) {
          const rad = (angleDeg * Math.PI) / 180;
          const tx = Math.round(capX + Math.cos(rad) * (cR - 0.4));
          const tz = Math.round(capZ + Math.sin(rad) * (cR - 0.4));
          const tLen = 1 + Math.floor(api.random() * 3);
          for (let dy = 1; dy <= tLen; dy++) {
            const ty = botY - dy;
            const gLevel = Math.max(0, Math.min(H - 1, Math.round(seatY + api.heightAt(tx, tz))));
            if (ty > gLevel + 1 && ty >= 0) {
              setVoxel(tx, ty, tz, (dy === tLen) ? palette.glowCore : palette.capOuter);
            }
          }
        }
      }
    } else if (st.capType === 1) {
      // Wide Parasol / Flared Shelf
      const botY = Math.max(stalkBaseY + 1, capY - 1);
      const topCapY = Math.min(H - 1, capY + 1);

      for (let y = botY; y <= topCapY; y++) {
        const layerR = (y === topCapY) ? cR * 0.6 : (y === capY ? cR : cR - 0.4);
        const minX = Math.max(0, Math.floor(capX - layerR));
        const maxX = Math.min(W - 1, Math.ceil(capX + layerR));
        const minZ = Math.max(0, Math.floor(capZ - layerR));
        const maxZ = Math.min(D - 1, Math.ceil(capZ + layerR));

        for (let x = minX; x <= maxX; x++) {
          for (let z = minZ; z <= maxZ; z++) {
            const d = Math.hypot(x - capX, z - capZ);
            if (d <= layerR) {
              if (y === topCapY) {
                setVoxel(x, y, z, palette.capOuter);
              } else if (y === capY) {
                setVoxel(x, y, z, (d >= layerR - 0.6) ? palette.capAccent : palette.glowSub);
              } else {
                // Underside glowing gills
                setVoxel(x, y, z, (d <= 1.2 || (x + z) % 2 === 0) ? palette.glowCore : palette.gills);
              }
            }
          }
        }
      }

      // Spore pearls hanging from edge
      for (let angleDeg = 0; angleDeg < 360; angleDeg += 60) {
        if (api.random() < 0.55) {
          const rad = (angleDeg * Math.PI) / 180;
          const tx = Math.round(capX + Math.cos(rad) * (cR - 0.3));
          const tz = Math.round(capZ + Math.sin(rad) * (cR - 0.3));
          const ty = botY - 1;
          const gLevel = Math.max(0, Math.min(H - 1, Math.round(seatY + api.heightAt(tx, tz))));
          if (ty > gLevel && ty >= 0) {
            setVoxel(tx, ty, tz, palette.glowCore);
          }
        }
      }
    } else {
      // Bulbous Lantern Pod
      const botY = Math.max(stalkBaseY + 1, capY - 1);
      const topCapY = Math.min(H - 1, capY + 2);

      for (let y = botY; y <= topCapY; y++) {
        const v = (y - botY + 0.5) / Math.max(1, topCapY - botY + 1);
        const layerR = cR * Math.sin(Math.PI * v);
        const minX = Math.max(0, Math.floor(capX - layerR));
        const maxX = Math.min(W - 1, Math.ceil(capX + layerR));
        const minZ = Math.max(0, Math.floor(capZ - layerR));
        const maxZ = Math.min(D - 1, Math.ceil(capZ + layerR));

        for (let x = minX; x <= maxX; x++) {
          for (let z = minZ; z <= maxZ; z++) {
            const d = Math.hypot(x - capX, z - capZ);
            if (d <= layerR) {
              const angle = Math.atan2(z - capZ, x - capX);
              const rib = Math.cos(angle * 4) > 0.2;
              if (d >= layerR - 0.7) {
                setVoxel(x, y, z, rib ? palette.capOuter : palette.glowCore);
              } else {
                setVoxel(x, y, z, palette.glowCore);
              }
            }
          }
        }
      }
    }
  }

  // 4. Crawling Root Spurs Across the Soil
  const numRoots = 3 + Math.floor(api.random() * 3);
  for (let r = 0; r < numRoots; r++) {
    const rootAngle = (r / numRoots) * Math.PI * 2 + (api.random() - 0.5) * 0.5;
    const rootDist = 2.5 + api.random() * 1.5;
    for (let d = 1.0; d <= rootDist; d += 0.6) {
      const rx = Math.round(cx + Math.cos(rootAngle) * d);
      const rz = Math.round(cz + Math.sin(rootAngle) * d);
      if (rx >= 0 && rx < W && rz >= 0 && rz < D) {
        const gY = Math.max(0, Math.min(H - 2, Math.round(seatY + api.heightAt(rx, rz))));
        setVoxel(rx, gY, rz, palette.rootBlock);
        if (d <= rootDist * 0.6) {
          setVoxel(rx, gY + 1, rz, palette.rootBlock);
        }
      }
    }
  }

  // 5. Solid Voxel Count Guarantee & 6-Connected Component Clean-Up
  let solidCount = 0;
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z]) solidCount++;
      }
    }
  }

  // If under 520 solid voxels, thicken the base mound to satisfy Rule 9
  let padRadius = 1;
  while (solidCount < 530 && padRadius <= 4) {
    for (let x = 1; x < W - 1; x++) {
      for (let z = 1; z < D - 1; z++) {
        const d = Math.hypot(x - cx, z - cz);
        if (d <= padRadius + 0.6) {
          const gY = Math.max(0, Math.min(H - 1, Math.round(seatY + api.heightAt(x, z))));
          for (let y = Math.min(gY, seatY); y <= seatY + 1; y++) {
            if (!grid[x][y][z]) {
              grid[x][y][z] = (y === seatY + 1) ? pavementTheme : plinthTheme;
              solidCount++;
            }
          }
        }
      }
    }
    padRadius++;
  }

  // Flood fill 6-connectivity from ground seat voxels
  const visited = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Uint8Array(D))
  );
  const queue = [];

  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const gY = Math.max(0, Math.min(H - 1, Math.round(seatY + api.heightAt(x, z))));
      for (let y = 0; y <= gY + 1; y++) {
        if (grid[x][y][z] && !visited[x][y][z]) {
          visited[x][y][z] = 1;
          queue.push([x, y, z]);
        }
      }
    }
  }

  const dxs = [1, -1, 0, 0, 0, 0];
  const dys = [0, 0, 1, -1, 0, 0];
  const dzs = [0, 0, 0, 0, 1, -1];

  let head = 0;
  while (head < queue.length) {
    const [qx, qy, qz] = queue[head++];
    for (let i = 0; i < 6; i++) {
      const nx = qx + dxs[i];
      const ny = qy + dys[i];
      const nz = qz + dzs[i];
      if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
        if (grid[nx][ny][nz] && !visited[nx][ny][nz]) {
          visited[nx][ny][nz] = 1;
          queue.push([nx, ny, nz]);
        }
      }
    }
  }

  // Prune any stray disconnected voxels
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z] && !visited[x][y][z]) {
          grid[x][y][z] = null;
        }
      }
    }
  }

  // 6. Emit blocks to world
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z]) {
          api.set(x, y, z, grid[x][y][z]);
        }
      }
    }
  }

  return {
    name: "glow_fungal_cluster",
    seatY: seatY,
    anchors: {
      spore_crown: [mainApex[0], mainApex[1], mainApex[2]],
    },
  };
}
